```javascript
const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
let sum = 0;
for (let i = 1; i <= n; i++) sum += input[i];
const avg = sum / n;
let out = '';
for (let i = 1; i <= n; i++) {
  out += (avg - input[i]) + '\n';
}
process.stdout.write(out);
